@function display-rgb($color) {
	@return unquote(
		"rgb(" + color.channel($color, "red") + ", " + color.channel($color, "green") + ", " +
			color.channel($color, "blue") + ")"
	);
}

@function display-rgb($color) {
	@return string.unquote(
		"rgb(" + color.channel($color, "red") + ", " + color.channel($color, "green") + ", " +
			color.channel($color, "blue") + ")"
	);
}

