@each $name, $value in $lte-palette {
	.card-#{$name},
	.bg-#{$name},
	.text-bg-#{$name} {
		--#{$lte-prefix}card-variant-bg: #{$value};
		--#{$lte-prefix}card-variant-bg-rgb: #{to-rgb($value)};
		--#{$lte-prefix}card-variant-color: #{lte-contrast($value)};
		--#{$lte-prefix}card-variant-color-rgb: #{to-rgb(lte-contrast($value))};
	}
}

@each $name, $value in $lte-palette {
	.callout-#{$name} {
		--#{$lte-prefix}callout-color: var(--#{$prefix}#{$name}-text-emphasis);
		--#{$lte-prefix}callout-bg: var(--#{$prefix}#{$name}-bg-subtle);
		--#{$lte-prefix}callout-border: var(--#{$prefix}#{$name}-border-subtle);
		--#{$lte-prefix}callout-link: var(--#{$prefix}#{$name}-text-emphasis);
		--#{$lte-prefix}callout-code-color: var(--#{$prefix}#{$name}-text-emphasis);
		--#{$prefix}callout-link-color: var(--#{$prefix}#{$name}-text-emphasis);
	}
}

@each $name, $value in $lte-palette {
	.direct-chat-#{$name} {
		--#{$lte-prefix}direct-chat-color: #{lte-contrast($value)};
		--#{$lte-prefix}direct-chat-bg: #{$value};
	}
}

@each $alias, $target in $lte-palette-aliases {
	@if not map.has-key($lte-palette, $target) {
		@error "adminlte-colors: alias `#{$alias}` points to `#{$target}`, which is not in $lte-palette.";
	}
	$lte-palette: map.merge($lte-palette, ($alias: map.get($lte-palette, $target)));
}

@each $name, $color in $theme-colors {
	.callout-#{$name} {
		--#{$lte-prefix}callout-color: var(--#{$prefix}#{$name}-text-emphasis);
		--#{$lte-prefix}callout-bg: var(--#{$prefix}#{$name}-bg-subtle);
		--#{$lte-prefix}callout-border: var(--#{$prefix}#{$name}-border-subtle);
		--#{$lte-prefix}callout-link: var(--#{$prefix}#{$name}-text-emphasis);
		--#{$lte-prefix}callout-code-color: var(--#{$prefix}#{$name}-text-emphasis);
		--#{$prefix}callout-link-color: var(--#{$prefix}#{$name}-text-emphasis);
	}
}

@each $name, $color in $theme-colors {
	.card-#{$name},
	.bg-#{$name},
	.text-bg-#{$name} {
		--#{$lte-prefix}card-variant-bg: #{$color};
		--#{$lte-prefix}card-variant-bg-rgb: #{to-rgb($color)};
		--#{$lte-prefix}card-variant-color: #{color-contrast($color)};
		--#{$lte-prefix}card-variant-color-rgb: #{to-rgb(color-contrast($color))};
	}
}

@each $name, $color in $theme-colors {
	.direct-chat-#{$name} {
		--#{$lte-prefix}direct-chat-color: #{color-contrast($color)};
		--#{$lte-prefix}direct-chat-bg: #{$color};
	}
}

@each $tone in (primary, info, warning, success, danger, secondary) {
	.faq-section-#{$tone} {
		border-left-color: var(--#{$prefix}#{$tone});

		.faq-section-icon {
			color: var(--#{$prefix}#{$tone}-text-emphasis);
			background: var(--#{$prefix}#{$tone}-bg-subtle);
		}
	}
}

