.docs-page .card > .card-body {
	padding: 1.5rem;
	font-size: 1rem;
	line-height: 1.7;
	color: var(--bs-body-color);
}

.docs-page .card > .card-body .h5 {
	padding-top: 1.5em;
	margin-top: 2.5em;
	font-size: 1.3rem;
	border-top: 1px solid var(--bs-border-color);
}

.docs-page .card > .card-body table {
	width: 100%;
	margin-top: 1.25rem;
	margin-bottom: 1.5rem;
	overflow: hidden;
	font-size: 0.95rem;
	border-collapse: collapse;
	border: 1px solid var(--bs-border-color);
	border-radius: 0.25rem;
}

.docs-page .card > .card-body table td {
	padding: 0.65rem 0.9rem;
	text-align: left;
	vertical-align: top;
	border-bottom: 1px solid var(--bs-border-color);
}

.docs-page .card > .card-body a:not(.btn):not(.nav-link) {
	color: var(--bs-link-color);
	text-decoration: underline;
	text-decoration-thickness: 1px;
	text-underline-offset: 3px;
}

.docs-page .card > .card-body hr {
	margin: 2.5rem 0;
	border: 0;
	border-top: 1px solid var(--bs-border-color);
	opacity: 1;
}

.docs-page .card > .card-body > p:first-of-type {
	margin-bottom: 2rem;
	font-size: 1.125rem;
	line-height: 1.6;
	color: var(--bs-body-color);
}

.docs-page .card > .card-body table td {
	padding: 0.65rem 0.9rem;
	text-align: right;
	vertical-align: top;
	border-bottom: 1px solid var(--bs-border-color);
}

.faq-page .faq-chips {
	display: flex;
	flex-wrap: wrap;
	gap: 0.5rem;
	justify-content: center;
}

.faq-page .faq-section-items .faq-item .faq-answer {
	padding: 1.1rem 1.25rem 1.1rem 3.85rem;
	font-size: 0.95rem;
	line-height: 1.65;
	color: var(--bs-body-color);
}

.faq-page .faq-cta h2 {
	margin: 0 0 0.5rem;
	font-size: 1.5rem;
	font-weight: 600;
	color: var(--bs-emphasis-color);
}

.faq-page .faq-cta-actions {
	display: inline-flex;
	flex-wrap: wrap;
	gap: 0.5rem;
	justify-content: center;
}

.faq-page .faq-section-items .faq-item .faq-answer {
	padding: 1.1rem 3.85rem 1.1rem 1.25rem;
	font-size: 0.95rem;
	line-height: 1.65;
	color: var(--bs-body-color);
}

.select2-container--default .select2-selection--multiple .select2-selection__rendered {
	display: contents;
	padding: 0;
	margin: 0;
	line-height: inherit;
}

.select2-container--default .select2-selection--multiple .select2-search--inline {
	display: flex;
	flex: 1 1 auto;
	align-items: center;
	min-width: 3rem;
}

.select2-container--default .select2-selection--multiple .select2-search--inline .select2-search__field {
	height: 1.5em;
	min-height: 0;
	padding: 0;
	margin: 0;
	font-family: inherit;
	font-size: 1rem;
	line-height: 1.5;
	color: inherit;
}

.select2-container--default .select2-search--dropdown .select2-search__field {
	padding: 0.25rem 0.5rem;
	font-size: 0.875rem;
	line-height: 1.5;
	color: var(--bs-body-color);
	background-color: var(--bs-body-bg);
	border: var(--bs-border-width) solid var(--bs-border-color);
	border-radius: var(--bs-border-radius-sm);
	transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
}

.form-control-sm + .select2-container--default .select2-selection--multiple {
	min-height: calc(1.5em + 0.5rem + calc(var(--bs-border-width) * 2));
	padding: 0.1875rem 0.5rem;
	font-size: 0.875rem;
	border-radius: var(--bs-border-radius-sm);
}

.form-control-lg + .select2-container--default .select2-selection--multiple {
	min-height: calc(1.5em + 1rem + calc(var(--bs-border-width) * 2));
	padding: 0.4375rem 1rem;
	font-size: 1.25rem;
	border-radius: var(--bs-border-radius-lg);
}

.text-bg-primary {
	--#{$lte-prefix}card-variant-bg: var(--#{$prefix}primary);
	--#{$lte-prefix}card-variant-bg-rgb: var(--#{$prefix}primary-rgb);
	--#{$lte-prefix}card-variant-color: var(--#{$lte-prefix}primary-color);
	--#{$lte-prefix}card-variant-color-rgb: var(--#{$lte-prefix}primary-color-rgb);
}

.toast-primary {
	--#{$prefix}toast-header-color: var(--#{$lte-prefix}primary-color);
	--#{$prefix}toast-header-bg: var(--#{$prefix}primary);
	--#{$prefix}toast-header-border-color: var(--#{$prefix}primary);
	--#{$prefix}toast-border-color: var(--#{$prefix}primary);
}

.select2-selection__rendered {
	display: contents;
	padding: 0;
	margin: 0;
	line-height: inherit;
}

.select2-search--inline {
	display: flex;
	flex: 1 1 auto;
	align-items: center;
	min-width: 3rem;
}

.select2-selection--multiple {
	border-color: $input-focus-border-color;
	outline: 0;

	@if $enable-shadows {
		@include box-shadow($input-box-shadow, $input-focus-box-shadow);
	} @else {
		box-shadow: $input-focus-box-shadow;
	}
}

.select2-selection--multiple {
	color: $form-select-disabled-color;
	cursor: default;
	background-color: $form-select-disabled-bg;
	border-color: $form-select-disabled-border-color;
}

.sr-only-focusable:focus {
	position: static !important;
	width: auto !important;
	height: auto !important;
	padding: inherit !important;
	margin: inherit !important;
	overflow: visible !important;
	clip: auto !important;
	white-space: normal !important;
}

.app-content-bottom-area {
	padding: $lte-app-content-bottom-area-padding-y $lte-app-content-bottom-area-padding-x;
	margin-top: auto;
	margin-bottom: $lte-app-content-bottom-area-margin-bottom;
	border-top: $lte-app-content-bottom-area-top-border;
}

.sidebar-wrapper {
	.nav-icon {
		min-width: 1.1rem;
		max-width: 1.1rem;
	}
}

.app-sidebar {
	min-width: 200px !important;
	max-width: 200px !important;
	max-height: none !important;
	margin-left: 0 !important;
}

.app-sidebar:not(:hover) {
	min-width: $lte-sidebar-mini-width-compact;
	max-width: $lte-sidebar-mini-width-compact;

	.sidebar-menu {
		.nav-link {
			width: $lte-sidebar-mini-width-compact - $lte-sidebar-padding-x * 2 !important;
		}
	}
}

.navbar-search-field {
	position: relative;
	width: var(--#{$lte-prefix}search-field-width);
	max-width: 100%;
	@include transition(width .2s ease-in-out);
}

.brand-image {
	float: left;
	width: auto;
	max-height: 33px;
	line-height: .8;
}

.logo-xs {
	visibility: hidden;
	animation-name: fadeOut;
	animation-duration: $lte-transition-speed;
	animation-fill-mode: both;
}

.brand-text {
	display: inline-block;
	max-width: 0;
	margin-left: 0;
	overflow: hidden;
}

.nav-arrow {
	visibility: hidden;
	animation-name: fadeOut;
	animation-duration: $lte-transition-speed;
	animation-fill-mode: both;
}

.nav.flex-column {
	> li {
		margin: 0;
		border-bottom: 1px solid $card-border-color;

		&:last-of-type {
			border-bottom: 0;
		}
	}
}

.card-title {
	float: left;
	margin: 0;
	font-size: $lte-card-title-font-size;
	font-weight: $lte-card-title-font-weight;
}

.direct-chat-messages {
	height: 250px;
	padding: 10px;
	overflow: auto;
	transform: translate(0, 0);
}

.end > .direct-chat-text {
	color: var(--#{$lte-prefix}direct-chat-color);
	background-color: var(--#{$lte-prefix}direct-chat-bg);
	border-color: var(--#{$lte-prefix}direct-chat-bg);

	&::after,
	&::before {
		border-left-color: var(--#{$lte-prefix}direct-chat-bg);
	}
}

.direct-chat-img {
	@include border-radius(50%);
	float: left;
	width: 40px;
	height: 40px;

	.end & {
		float: right;
	}
}

.faq-chips {
	display: flex;
	flex-wrap: wrap;
	gap: .5rem;
	justify-content: center;
}
